    const quizForm = document.getElementById('quizForm');
    const resultMessage = document.getElementById('result');

    quizForm.addEventListener('submit', (e) => {
        e.preventDefault();

        // Collect selected answers for each question
        const question1 = Array.from(
            document.querySelectorAll('input[name="question1"]:checked')
        ).map(input => input.value);

        const question2 = Array.from(
            document.querySelectorAll('input[name="question2"]:checked')
        ).map(input => input.value);

        const question3 = Array.from(
            document.querySelectorAll('input[name="question3"]:checked')
        ).map(input => input.value);

        // Define correct answers
        const correctAnswers = {
            question1: ['javascript', 'typescript'],
            question2: ['java', 'go', 'csharp'],
            question3: ['cpp', 'kotlin']
        };

        // Check if selections match correct answers
        const isQuestion1Correct = areAnswersEqual(question1, correctAnswers.question1);
        const isQuestion2Correct = areAnswersEqual(question2, correctAnswers.question2);
        const isQuestion3Correct = areAnswersEqual(question3, correctAnswers.question3);

        const correctCount = [isQuestion1Correct, isQuestion2Correct, isQuestion3Correct].filter(Boolean).length;

        // Display result
        displayResult(correctCount, isQuestion1Correct, isQuestion2Correct, isQuestion3Correct);
    });

    function areAnswersEqual(userAnswers, correctAnswers) {
        if (userAnswers.length !== correctAnswers.length) return false;
        const sorted1 = [...userAnswers].sort();
        const sorted2 = [...correctAnswers].sort();
        return sorted1.every((val, idx) => val === sorted2[idx]);
    }

    function displayResult(correctCount, q1, q2, q3) {
        let message = `<strong>Quiz Complete!</strong><br>`;
        message += `You got ${correctCount} out of 3 questions correct.`;

        resultMessage.classList.remove('success', 'info');

        if (correctCount === 3) {
            message += `<br>Perfect score! 🎉`;
            resultMessage.classList.add('success');
        } else if (correctCount >= 2) {
            message += `<br>Great effort! Keep learning. 📚`;
            resultMessage.classList.add('success');
        } else {
            message += `<br>Good attempt! Review the answers and try again. 💪`;
            resultMessage.classList.add('info');
        }

        // Show which questions were correct
        message += `<br><br><small>Q1: ${q1 ? '✓' : '✗'} | Q2: ${q2 ? '✓' : '✗'} | Q3: ${q3 ? '✓' : '✗'}</small>`;

        resultMessage.innerHTML = message;
        resultMessage.style.display = 'block';

        // Scroll to result
        resultMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
});
